 "content": "def transform(grid):
    """Stamp the embedded line motif, centered on each foreign marker."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    counts = {}
    for row in g:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)

    # Locate the longest contiguous non-background line, horizontal or vertical.
    best = None
    for r, row in enumerate(g):
        c = 0
        while c < w:
            if row[c] == bg:
                c += 1
                continue
            start = c
            while c < w and row[c] != bg:
                c += 1
            seq = row[start:c]
            if best is None or len(seq) > len(best[0]):
                best = (seq[:], r, start, (0, 1))
    for c in range(w):
        r = 0
        while r < h:
            if g[r][c] == bg:
                r += 1
                continue
            start = r
            while r < h and g[r][c] != bg:
                r += 1
            seq = [g[y][c] for y in range(start, r)]
            if best is None or len(seq) > len(best[0]):
                best = (seq, start, c, (1, 0))

    motif, ar, ac, (dr, dc) = best
    motif_colors = set(motif)
    anchor = len(motif) // 2
    markers = [(r, c) for r in range(h) for c in range(w)
               if g[r][c] != bg and g[r][c] not in motif_colors
               and not (dr == 0 and r == ar and ac <= c < ac + len(motif))
               and not (dc == 0 and c == ac and ar <= r < ar + len(motif))]
    for r, c in markers:
        for i, value in enumerate(motif):
            y, x = r + (i - anchor) * dr, c + (i - anchor) * dc
            if 0 <= y < h and 0 <= x < w:
                g[y][x] = value
    return g


